      $('sea-receipt').hidden=clock>receipt.until||receipt.until===0;if(!$('sea-receipt').hidden){const goods=Object.entries(receipt.cargo).map(([id,n])=>n+' '+by(D.goods,id).name.toLowerCase());$('sea-receipt').textContent=[...goods.slice(0,2),goods.length>2?'more cargo':null,receipt.coins?'+'+receipt.coins+'c':null,...Object.entries(receipt.heals).slice(0,2).map(([name,hp])=>name+' +'+hp+' hull')].filter(Boolean).join(' / ');}
      $('formation').innerHTML=game.formation[0].toUpperCase()+game.formation.slice(1)+' formation <kbd>'+(inputMode==='controller'?'D-pad': 'F')+'</kbd>';
      const signal=game.nearbySignal(),action=$('context-action');action.hidden=!site&&near.distance>190&&!game.production&&!signal&&!game.encounter;if(game.production)action.textContent='Recall workboat (E)';else if(game.encounter)action.textContent='Leave operation (E)';else if(near.distance<190)action.textContent='Dock in '+near.port.name+' (E)';else if(signal)action.textContent='Investigate signal (E)';else if(site)action.textContent=site.type==='fish'?'Deploy nets (E)':'Extract oil (E)';if(inputMode==='controller')action.textContent=action.textContent.replace('(E)','('+controller.labels().confirm+')');
      $('operation').hidden=!game.production;if(game.production){const op=game.production;$('operation-text').textContent=(op.site.type==='fish'?'Fishing: ':'Extracting: ')+op.site.name;$('operation-bar').style.width=op.progress/op.plan.duration*100+'%';$('operation-detail').textContent=game.workStatus();$('operation-warning').hidden=!op.approach;$('operation-warning').textContent=op.approach?({rush:'Fast boats',guns:'Gunboats',mixed:'Raiders'})[op.approach.style]+' from '+WidewakeWork.bearing(op.approach.angle)+' / '+Math.max(1,Math.ceil(game.spawnTimer))+'s':'';}
